package method_argument2;

public class Trinagle_without_parameter_without_returnvalue {

	
	public void triangle()
	{
		double b=20;
		double h=18;
		double s=b*h;
		double a=0.5*s;
		System.out.println(a);
	}
	
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Trinagle_without_parameter_without_returnvalue t=new Trinagle_without_parameter_without_returnvalue();
		t.triangle();

	}

}
